const escapeHTML = (s) => String(s).replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
export function createServiceSelector(preview = false) {
 return `<div class="v79-service-selector">${Object.entries(SOLUTION_STORIES).map(([slug,s],i)=>`<a class="v79-service-tile" href="${preview?slug+'.html':'/services/'+slug}"><span class="v79-tile-icon" aria-hidden="true"><svg viewBox="-40 -34 80 68">${s.thumbnail}</svg></span><span><strong>${escapeHTML(s.title)}</strong><span>${escapeHTML(s.headline)}</span></span><span class="v79-tile-arrow" aria-hidden="true">→</span></a>`).join('')}</div>`;
}
export function createStoryMarkup(slug) {
 const s=SOLUTION_STORIES[slug]; if(!s)return '';
 const steps=[s.overview,...s.parts,s.final];
 return `<section class="v79-solution" data-solution="${slug}" aria-label="Explore ${escapeHTML(s.title)}"><header class="v79-story-heading"><div><p class="v79-story-eyebrow">Inside the solution</p><h2>${escapeHTML(s.headline)}</h2><p>${escapeHTML(s.summary)}</p></div><button data-motion aria-pressed="false" type="button">Reduce motion</button></header><div class="v79-story-layout"><div class="v79-story-chapters">${steps.map((p,i)=>`<article class="v79-story-chapter${i===0?' is-active':''}" data-chapter="${i}"><span class="v79-chapter-number">${String(i).padStart(2,'0')}</span><div><h3>${escapeHTML(p.title)}</h3><p>${escapeHTML(p.detail)}</p><strong class="v79-story-outcome">${escapeHTML(p.outcome)}</strong></div></article>`).join('')}</div><figure class="v79-story-figure"><div class="v79-story-canvas"><div class="v79-art-meta"><span>V79 / ${escapeHTML(s.title)}</span><span data-view>Complete view</span></div><div class="v79-artwork">${s.artwork}</div><figcaption><strong data-caption>${escapeHTML(s.overview.outcome)}</strong><span data-count>00 / 06</span></figcaption><div class="v79-story-progress"><span data-progress></span></div></div><div class="v79-story-controls"><div role="group" aria-label="Choose an explanation">${steps.map((p,i)=>`<button type="button" data-step="${i}" aria-label="${escapeHTML(p.title)}" ${i===0?'aria-current="step"':''}><span></span></button>`).join('')}</div><div><button type="button" data-prev aria-label="Previous explanation" disabled>←</button><button type="button" data-next aria-label="Next explanation">→</button></div></div><p class="v79-story-note">AI-generated illustrative imagery, not actual V79 installations or staff. Equipment, tools and arrangements depend on the agreed scope. <span data-static-note></span></p></figure></div><div class="v79-story-scenario"><div><p class="v79-story-eyebrow">Try a scenario</p><h3>What happens when something changes?</h3><p>This example explains the idea. It does not connect to customer systems.</p></div><div class="v79-scenario-panel"><span class="v79-scenario-label">Illustrative demonstration</span><p role="status" data-scenario-message>${escapeHTML(s.scenario[2])}</p><div><button type="button" data-scenario aria-pressed="false">${escapeHTML(s.scenario[0])}</button><button type="button" data-pause aria-pressed="false">Pause activity</button></div></div></div></section>`;
}
export function mountSolutionStory(root) {
 const slug=root.dataset.solution,story=SOLUTION_STORIES[slug]; if(!story)return ()=>{};
 const chapters=[...root.querySelectorAll('[data-chapter]')],parts=[...root.querySelectorAll('[data-part]')],buttons=[...root.querySelectorAll('[data-step]')];
 const os=matchMedia('(prefers-reduced-motion: reduce)'),compact=matchMedia('(max-width:760px), (max-height:680px)');
 const motion=root.querySelector('[data-motion]'),prev=root.querySelector('[data-prev]'),next=root.querySelector('[data-next]'),pause=root.querySelector('[data-pause]');
 const all=[story.overview,...story.parts,story.final]; let active=0,spread=0,userReduced=false,paused=false,scenario=false,frame=0,disposed=false;
 const events=[];const listen=(target,event,callback,options)=>{target.addEventListener(event,callback,options);events.push(()=>target.removeEventListener(event,callback,options))};
 function reduced(){return os.matches||userReduced}
 function pose(){const explode=active>0&&active<6&&!reduced()&&!compact.matches;root.classList.toggle('is-exploded',explode);root.classList.toggle('is-complete',active===6||reduced()||compact.matches);parts.forEach((p,i)=>{let [x,y]=story.offsets[i];if(i+1===active)x-=16;p.style.transform=explode?`translate(${x*spread}px,${y*spread}px)`:'translate(0px,0px)';p.classList.toggle('is-dim',explode&&i+1!==active);p.classList.toggle('is-focused',i+1===active)});}
 function render(){root.classList.toggle('is-reduced',reduced());root.classList.toggle('is-paused',paused||reduced());chapters.forEach((p,i)=>p.classList.toggle('is-active',i===active));buttons.forEach((b,i)=>{if(i===active)b.setAttribute('aria-current','step');else b.removeAttribute('aria-current')});root.querySelector('[data-caption]').textContent=all[active].outcome;root.querySelector('[data-view]').textContent=active===0?'Complete view':active===6?'Working together':`Part ${active} of 5`;root.querySelector('[data-count]').textContent=String(active).padStart(2,'0')+' / 06';root.querySelector('[data-progress]').style.width=(active/6*100)+'%';prev.disabled=active===0;next.disabled=active===6;motion.textContent=os.matches?'Motion reduced by device':userReduced?'Enable motion':'Reduce motion';motion.disabled=os.matches;motion.setAttribute('aria-pressed',String(reduced()));pause.textContent=reduced()?'Activity reduced':paused?'Resume activity':'Pause activity';pause.disabled=reduced();pause.setAttribute('aria-pressed',String(paused||reduced()));root.querySelector('[data-static-note]').textContent=reduced()?'Static view. All explanations remain below.':'';pose();}
 function update(){frame=0;if(disposed||compact.matches||reduced())return;const target=innerHeight*.46;const centres=chapters.map(c=>{const r=c.getBoundingClientRect();return r.top+Math.min(110,r.height*.42)});let index=0,distance=Infinity;centres.forEach((v,i)=>{const d=Math.abs(v-target);if(d<distance){distance=d;index=i}});const p=Math.max(0,Math.min(1,(target-centres[0])/(centres[6]-centres[0])));spread=Math.max(0,Math.min(1,p*7,(1-p)*7));if(index!==active){active=index;render()}else pose();}
 function schedule(){if(!frame&&!document.hidden&&!disposed)frame=requestAnimationFrame(update)}
 function go(n){active=Math.max(0,Math.min(6,n));spread=active>0&&active<6?1:0;render();if(!compact.matches&&!reduced())chapters[active].scrollIntoView({behavior:'smooth',block:'center'});}
 listen(window,'scroll',schedule,{passive:true});listen(window,'resize',()=>{render();schedule()},{passive:true});listen(document,'visibilitychange',()=>{root.classList.toggle('is-hidden',document.hidden);if(!document.hidden)schedule()});
 listen(os,'change',()=>{render();schedule()});listen(compact,'change',()=>{render();schedule()});
 buttons.forEach(b=>listen(b,'click',()=>go(Number(b.dataset.step))));listen(prev,'click',()=>go(active-1));listen(next,'click',()=>go(active+1));listen(motion,'click',()=>{userReduced=!userReduced;render();schedule()});listen(pause,'click',()=>{paused=!paused;render()});
 listen(root.querySelector('[data-scenario]'),'click',e=>{scenario=!scenario;e.currentTarget.setAttribute('aria-pressed',String(scenario));e.currentTarget.textContent=story.scenario[scenario?1:0];root.querySelector('[data-scenario-message]').textContent=story.scenario[scenario?3:2];root.querySelector('.v79-scenario-panel').classList.toggle('is-scenario',scenario);root.classList.toggle('is-outage',scenario&&story.kind==='rack')});
 root.classList.add('is-enhanced');render();schedule();return ()=>{disposed=true;cancelAnimationFrame(frame);events.forEach(fn=>fn());root.classList.remove('is-enhanced')};
}
